const raw = $input.first().json;
const topic = (raw.chatInput || '').trim();

// Empty check
if (!topic) {
  return [{ json: { valid: false, error: 'Topic is empty.', topic: null } }];
}

// Too long
if (topic.length > 300) {
  return [{ json: { valid: false, error: 'Topic too long. Keep it under 300 characters.', topic: null } }];
}

// No real words — must have at least one word with 3+ letters
if (!/\b[a-zA-Z]{3,}\b/.test(topic)) {
  return [{ json: { valid: false, error: 'Invalid topic. Please enter meaningful text.', topic: null } }];
}

// Gibberish check — no vowels at all = gibberish
const words = topic.toLowerCase().match(/\b[a-z]{3,}\b/g) || [];
const gibberishCount = words.filter(w => !/[aeiou]/.test(w)).length;

if (words.length > 0 && gibberishCount / words.length > 0.6) {
  return [{ json: { valid: false, error: 'Topic looks like gibberish. Please enter a real topic.', topic: null } }];
}

return [{ json: { valid: true, error: null, topic: topic } }];

// ── PLATFORM VARIATIONS NODE ─────────────────────────────────
// Takes the Gemini-generated core content and creates
// platform-specific variations in tone and formatting.
// All content is 100% dynamic — no hardcoding.

const data = $input.first().json;

const { caption, hashtags_string, cta, topic } = data;

// Pick top 3 hashtags for LinkedIn (professional platforms use fewer)
const topHashtags = data.hashtags.slice(0, 3).map(h => `#${h}`).join(' ');

// ── Instagram: visual-first, emoji-rich, hashtag-heavy ──
const instagram = {
  content: `✨ ${caption}\n\n👉 ${cta}\n\n${hashtags_string} #Reels #Viral #Explore`,
  tone: 'Visual, emoji-rich, hashtag-heavy',
  platform: 'Instagram'
};

// ── LinkedIn: professional, insight-driven, thought-leadership ──
const linkedin = {
  content: `${caption}\n\nKey Takeaway: Staying ahead on "${topic}" is no longer optional — it's a competitive necessity.\n\n${cta}\n\n${topHashtags} #ProfessionalGrowth #Innovation`,
  tone: 'Professional, insight-driven, thought-leadership',
  platform: 'LinkedIn'
};

// ── Facebook: conversational, community-focused, story-style ──
const facebook = {
  content: `Hey everyone! 👋\n\n${caption}\n\nWe'd love to hear your thoughts — ${cta}\n\n${hashtags_string}`,
  tone: 'Friendly, community-focused, conversational',
  platform: 'Facebook'
};

// ── YouTube: SEO-optimised description with chapter placeholders ──
const youtube = {
  content: `${caption}\n\n🔔 SUBSCRIBE for more content on ${topic}!\n\n${cta}\n\n⏱️ CHAPTERS:\n00:00 – Introduction\n01:30 – Deep Dive\n05:00 – Key Insights\n08:00 – Final Thoughts\n\n${hashtags_string}`,
  tone: 'SEO-optimised, informative, subscriber-focused',
  platform: 'YouTube'
};

return [{
  json: {
    ...data,
    platforms: {
      instagram,
      linkedin,
      facebook,
      youtube
    }
  }
}];

const data = $('Map Platform Content for Sheets').first().json;
const imageUrl = $('Generate Image (Leonardo AI)').first().json.image_url;

const summary = {
  status: 'success',
  workflow: 'AI Social Media Automation',
  completed_at: new Date().toISOString(),

  topic_processed: data.topic,

  content_generated: {
    caption: data.caption,
    hashtags: data.hashtags,
    cta: data.cta,
    image_url: imageUrl
  },

  platforms_posted: ['Instagram', 'LinkedIn'],

  logged_to_google_sheets: true,

  message: `✅ Done! Content for "${data.topic}" has been generated, posted to Instagram & LinkedIn, and logged to Google Sheets.`
};

return [{ json: summary }];

// ── GEMINI API ERROR HANDLER ─────────────────────────────────
// Catches failures from the Gemini HTTP Request node.
// Extracts a useful error message and formats it cleanly.

const raw = $input.first().json;
const topic = $('Validate Input').first().json.topic || 'unknown';

let errorMessage = 'Unknown error contacting Gemini API';
if (raw.error) {
  errorMessage = `Gemini API Error ${raw.error.code || ''}: ${raw.error.message || raw.error}`;
} else if (raw.message) {
  errorMessage = raw.message;
}

return [{
  json: {
    status: 'error',
    error_type: 'gemini_api_failure',
    error_message: errorMessage,
    topic: topic,
    timestamp: new Date().toISOString(),
    suggestion: 'Check your GEMINI_API_KEY, quota limits, and network connectivity.'
  }
}];

let raw = $json.content.parts[0].text;

// remove ```json and ```
raw = raw.replace(/```json/g, "").replace(/```/g, "").trim();

return [{ json: JSON.parse(raw) }];

const data = $input.first().json;

return [
  {
    json: {
      ...data,
      platform: "Instagram",
      content: data.platforms.instagram.content
    }
  },
  {
    json: {
      ...data,
      platform: "LinkedIn",
      content: data.platforms.linkedin.content
    }
  }
];

const variations = $('Create Platform Variations').first().json;
const imageUrl = $('Generate Image (Leonardo AI)').first().json.image_url;

// Fix hashtags — array to clean string
const hashtags = Array.isArray(variations.hashtags)
  ? variations.hashtags.map(h => h.startsWith('#') ? h : `#${h}`).join(' ')
  : variations.hashtags_string || '';

return ['instagram', 'linkedin'].map(key => {
  const p = variations.platforms[key];
  return {
    json: {
      topic:     variations.topic,
      caption:   variations.caption,
      hashtags:  hashtags,
      cta:       variations.cta,
      image_url: imageUrl,
      platform:  p.platform,
      content:   p.content
    }
  };
});
